R=pathlib.Path('results/v48');a=json.loads((R/'analysis.json').read_text());tests=[json.loads(s) for s in (R/'tests/integration.jsonl').read_text().splitlines()];assert len(tests)==18 and all(x['status']=='PASSED' for x in tests);stages=['training','heldout']
