def save(fig,name):
 fig.tight_layout();fig.savefig(R/(name+'.png'),dpi=180);fig.savefig(R/(name+'.pdf'),metadata={'CreationDate':None,'ModDate':None});fig.savefig(R/(name+'.svg'),metadata={'Date':None});plt.close(fig)
