 ax.axvline(0,color='#777',ls=':');ax.axvline(target,color='#b32929',ls='--');ax.set_yticks([0,1],['Training','Held-out']);ax.set_ylim(-.7,1.7);ax.set_xlabel('Candidate 20ms versus baseline 5ms: paired relative change (%)');ax.set_title(title,loc='left',fontweight='bold');ax.spines[['top','right']].set_visible(False)
