 values=[m[v]['components'].get(category,{}).get('cpu_seconds',0)/9 for v in ('baseline','candidate')];ax.bar(['Baseline 5ms','Candidate 20ms'],values,bottom=bottom,label=category);bottom=[x+y for x,y in zip(bottom,values)]
